SELECT * FROM ( SELECT a.*, ROWNUM rnum FROM ( SELECT notice_id, title, writer, is_visible, created_at FROM notice WHERE is_visible = 'Y'
AND (title LIKE '%' || #{keyword} || '%')
ORDER BY created_at DESC ) a WHERE ROWNUM <= #{offset} + #{limit}) WHERE rnum > #{offset}

		SELECT notice_id, title, writer, is_visible, created_at
        FROM (
            SELECT a.*, ROWNUM rnum
            FROM (
                SELECT notice_id, title, writer, is_visible, created_at
                FROM notice

                    WHERE title LIKE '%' || #{keyword} || '%'

                ORDER BY created_at DESC
            ) a
            WHERE ROWNUM <= #{offset} + #{limit}
        )
        WHERE rnum > #{offset}

SELECT notice_id, title, content, writer, is_visible, created_at, updated_at
FROM notice
WHERE notice_id = #{notice_id}

mapper.update:
		UPDATE notice
        SET title = #{title}, content = #{content}, is_visible = #{is_visible,jdbcType=VARCHAR}, updated_at = SYSDATE
        WHERE notice_id = #{notice_id}
